nextflow_process {

    name "Test Process FAMSA_ALIGN"
    script "../main.nf"
    process "FAMSA_ALIGN"

    tag "modules"
    tag "modules_nfcore"
    tag "famsa"
    tag "famsa/align"
    tag "famsa/guidetree"

    test("sarscov2 - fasta - uncompressed") {

        when {
            process {
                """
                input[0] = [ [ id:'test_uncompressed' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true)
                ]
                input[1] = [[:], []]
                input[2] = false
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("sarscov2 - fasta - compressed") {

        when {
            process {
                """
                input[0] = [ [ id:'test_compressed' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true)
                ]
                input[1] = [[:], []]
                input[2] = true
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("sarscov2 - fasta - guide_tree") {
        setup {
            run("FAMSA_GUIDETREE") {
                script "../../guidetree/main.nf"
                process {
                    """
                    input[0] = [ [ id:'test_guide_tree' ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true)
                    ]
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = [ [ id:'test_guide_tree' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true)
                ]
                input[1] = FAMSA_GUIDETREE.out.tree
                input[2] = true
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 - fasta - uncompressed - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [ id:'test_stub' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true)
                ]
                input[1] = [[:], []]
                input[2] = false
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }
}

